(function(){function q(s,c){return(c||document).querySelector(s)}function qa(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))}function close(){document.body.classList.remove('sidebar-open');qa('.app-shell').forEach(function(e){e.classList.remove('sidebar-open')})}document.addEventListener('click',function(e){var t=e.target;if(t.closest&&t.closest('.mq-sidebar-toggle')){e.preventDefault();document.body.classList.toggle('sidebar-open');var shell=t.closest('.app-shell');if(shell){shell.classList.toggle('sidebar-open')}return}if(t.classList&&t.classList.contains('mq-sidebar-overlay')){close();return}if(t.closest&&t.closest('.sidebar .nav-item')){if(window.innerWidth<769){close()}}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){close()}});var timer;window.addEventListener('resize',function(){clearTimeout(timer);timer=setTimeout(function(){if(window.innerWidth>768){close()}},120)},{passive:true});})();
